    style: 'currency',
    currency: currency,
  }).format(amount);
}

def flatten(nested_list, depth=float('inf')):
    result = []
    for item in nested_list:
        if isinstance(item, list) and depth > 0:
            result.extend(flatten(item, depth - 1))
        else:
            result.append(item)
    return result

